def plan(wps, held=None, ignore=(), every=3, verbose=True):
    pv = ep.preview(wps)
    qs = pv.get("q") or []
    chk = ep.check_batch(qs[::every] + ([qs[-1]] if qs else []), held=held, ignore=ignore) if qs else []
    bad = []
    for i, c in enumerate(chk):
        if not c["collision_free"]:
            for ct in c["contacts"]:
                bad.append((i, ct["link"], ct["obstacle"], round(ct["clearance_m"],4)))
    if verbose:
        print("preview ok:", pv["ok"], "| dur", pv.get("duration"), "min_dur", pv.get("min_duration"), "| n_q", len(qs), "|", rh.explain(pv))
        iss = rh.issues(pv, severity=None)
        if iss: print("  issues:", iss[:6])
        print("  collision-free all:", all(c["collision_free"] for c in chk), "contacts:", bad[:12])
    return pv, bad
